#include <stdio.h>

typedef struct { int locks[10]; } LockManager;

void lm_init(LockManager *m) { for (int i = 0; i < 10; i++) m->locks[i] = 0; }

int acquire_lock(LockManager *m, int lock_id) {
    if (m->locks[lock_id]) { printf("Lock %d: ACQUIRE FAIL (held)\n", lock_id); return 0; }
    m->locks[lock_id] = 1;
    printf("Lock %d: ACQUIRE OK\n", lock_id);
    return 1;
}

void release_lock(LockManager *m, int lock_id) {
    m->locks[lock_id] = 0;
    printf("Lock %d: RELEASED\n", lock_id);
}

int main() {
    LockManager lm;
    lm_init(&lm);
    // Client 1
    printf("Client 1: "); acquire_lock(&lm, 0);
    // Client 2
    printf("Client 2: "); acquire_lock(&lm, 0);
    // Client 1 releases
    printf("Client 1: "); release_lock(&lm, 0);
    // Client 2 retries
    printf("Client 2: "); acquire_lock(&lm, 0);
    return 0;
}
